<p class="eyebrow">Deposit review</p><h1><?= e($deposit['reference']) ?></h1><section class="card"><p><?= e($deposit['email']) ?> · <?= e($deposit['method_name']) ?></p><dl class="detail-list"><dt>Requested</dt><dd><?= money((int)$deposit['requested_amount_minor']) ?></dd><dt>Expected credit</dt><dd><?= money((int)$deposit['expected_credit_minor']) ?></dd><dt>Status</dt><dd><?= e($deposit['status']) ?></dd></dl><form method="post" action="<?= e(route('admin.deposits.action',['deposit'=>$deposit['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><textarea name="notes" placeholder="Internal notes"></textarea><label>Rejection reason<input name="reason"></label><div class="button-row"><button class="button button-secondary" name="action" value="review">Under review</button><button class="button" name="action" value="approve">Approve and credit</button><button class="button danger" name="action" value="reject">Reject</button></div></form></section><section class="card"><h2>Submitted details</h2><?php foreach($values as $v): ?><p><strong><?= e($v['field_label']) ?>:</strong> <?= e($v['value_text']) ?></p><?php endforeach; ?><h2>Private receipts</h2><?php foreach($files as $file): ?><p><a href="<?= e(route('admin.deposits.file',['deposit'=>$deposit['id'],'file'=>$file['id']])) ?>"><?= e($file['original_filename']) ?></a></p><?php endforeach; ?></section>
